pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        // make the test contract the initial owner for setup simplicity
        c.transferOwnership(address(this));
    }
    function testFuzz_property(address nonOwner) public {
        // Ensure nonOwner is not the current owner, otherwise owned() should succeed
        vm.assume(nonOwner != address(this));
        vm.assume(nonOwner != address(0));

        address ownerBefore = c.owner();

        vm.prank(nonOwner);
        try c.owned() {
            // If it does not revert, the call succeeded
            // In the reference, this path should never be reached for a non-owner
            // We assert that it did revert, so success is a failure
            assertTrue(false);
        } catch {
            // Assert that the owner remained unchanged after the revert
            assertTrue(c.owner() == ownerBefore);
        }
    }
}

