pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address nonOwner) public {
        // Ensure nonOwner is not the initial owner (address(0) before any transfer)
        // and not the contract itself, just a generic fuzzed address.
        vm.assume(nonOwner != address(0));
        // The initial owner is the deployer of setUp, which is this test contract.
        // We need nonOwner to be different from the current owner.
        vm.assume(nonOwner != address(this));

        // nonOwner attempts to steal ownership
        vm.prank(nonOwner);
        try c.transferOwnership(nonOwner) {
            // In correct version, this should revert because nonOwner is not the owner.
            // In buggy version, this succeeds and owner changes to nonOwner.
            // So, after the attempt, owner must NOT be nonOwner under the correct contract.
            // If it doesn't revert, we check the result.
            assertTrue(c.owner() != nonOwner);
        } catch {
            // Revert is expected for correct version.
            // We just assert something trivially true to keep a single assertion,
            // but we need the same assertion to verify correctness post-call.
            // Actually, the rule is: after any call by nonOwner, owner remains unchanged.
            // So we can assert that owner is still the original deployer.
            assertTrue(c.owner() == address(this));
        }
    }
}

