pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwnerCandidate) public {
        vm.assume(caller != address(0));
        vm.assume(newOwnerCandidate != address(0));
        // Set owner to caller, so caller is authorized (or not, depending on contract version)
        vm.prank(caller);
        c.transferOwnership(caller);

        // Now try to transfer ownership to newOwnerCandidate as the caller
        vm.prank(caller);
        bool ok = true;
        try c.transferOwnership(newOwnerCandidate) {
        } catch {
            ok = false;
        }
        // If the call succeeded, the new owner must be newOwnerCandidate.
        // The buggy version inverts the modifier: caller != owner (caller is owner, so it reverts) => ok is false.
        // The reference version allows owner to call => ok is true and owner changes.
        if (ok) {
            assertEq(c.owner(), newOwnerCandidate);
        } else {
            assertEq(c.owner(), caller);
        }
    }
}

