// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        // Set the initial owner to the caller so that the fuzzer can explore the scenario
        vm.prank(caller);
        c.transferOwnership(caller);

        bool ok;
        vm.prank(caller);
        try c.transferOwnership(newOwner) { ok = true; } catch { ok = false; }

        // If the call succeeded, the owner must be the intended newOwner.
        // The reference contract always sets owner = newOwner on success.
        // The buggy contract allows non-owners to call transferOwnership without changing owner,
        // or changes it only for the true owner; the fuzzer will find a case where ok is true but owner != newOwner.
        assertTrue(!ok || c.owner() == newOwner);
    }
}
